<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\Profile; use App\Models\Opportunity; use App\Models\OpportunityReviewLog; use App\Models\OcdNotification; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ProfileReviewController extends Controller {
 public function submit(Request $request) { $p=$request->user()->profile; $missing=[]; foreach(['public_name','professional_title','country_id','bio'] as $field) if(blank($p->{$field}))$missing[]=$field; if(!$p->avatar_path)$missing[]='avatar'; if($missing)return response()->json(['message'=>'Complétez les informations obligatoires avant la soumission.','missing'=>$missing],422); $p->update(['review_status'=>'pending','submitted_at'=>now(),'review_note'=>null,'is_public'=>false]); return response()->json(['message'=>'Votre profil a été envoyé à OCD pour validation.','data'=>$p->fresh()]); }
 public function queue() { return response()->json(['data'=>Profile::with(['user:id,name,email','country','category'])->where('review_status','pending')->latest('submitted_at')->paginate(30)]); }
 public function review(Request $request,int $profile) {
  $data=$request->validate(['decision'=>['required','in:approved,rejected'],'note'=>['nullable','string','max:2000']]);
  $p=Profile::with('user')->findOrFail($profile);
  $p->update(['review_status'=>$data['decision'],'reviewed_at'=>now(),'reviewed_by'=>$request->user()->id,'review_note'=>$data['note']??null,'is_public'=>$data['decision']==='approved']);
  OcdNotification::create(['user_id'=>$p->user_id,'type'=>'profile_'.$data['decision'],'title'=>$data['decision']==='approved'?'Profil approuvé':'Corrections demandées sur votre profil','message'=>$data['decision']==='approved'?'Votre profil OCD a été approuvé.':('Votre profil nécessite des corrections avant validation.'.(filled($data['note']??null)?' Motif : '.$data['note']:'')),'data'=>['profile_id'=>$p->id,'review_status'=>$data['decision']]]);
  return response()->json(['message'=>$data['decision']==='approved'?'Profil approuvé.':'Profil refusé, corrections demandées.','data'=>$p->fresh()]);
 }
 public function publicProfiles(Request $request) { $q=Profile::with(['country','category','skills'])->where('review_status','approved')->where('is_public',true)->whereNotNull('avatar_path'); if($request->filled('q'))$q->where(fn($w)=>$w->where('public_name','like','%'.$request->query('q').'%')->orWhere('professional_title','like','%'.$request->query('q').'%')); return response()->json($q->latest()->paginate(20)); }
 public function reviewOpportunities(Request $request) { $q=Opportunity::with('owner:id,name,email')->whereIn('status',['pending_review','changes_requested','suspended']); if($request->filled('country')) $q->where('country_name','like','%'.trim($request->query('country')).'%'); if($request->filled('category')) $q->where('category',$request->query('category')); return response()->json(['data'=>$q->latest()->paginate(30)]); }
 public function decideOpportunity(Request $request,int $opportunity) { $data=$request->validate(['decision'=>['required','in:published,rejected,changes_requested,suspended'],'note'=>['required_if:decision,rejected,changes_requested,suspended','nullable','string','max:2000']]); $item=Opportunity::findOrFail($opportunity); DB::transaction(function() use($request,$data,$item){ $before=$item->status; $published=$data['decision']==='published'; $item->update(['status'=>$data['decision'],'published_at'=>$published?($item->published_at??now()):null,'review_note'=>$data['note']??null,'reviewed_at'=>now(),'reviewed_by'=>$request->user()->id]); OpportunityReviewLog::create(['opportunity_id'=>$item->id,'reviewer_id'=>$request->user()->id,'action'=>$data['decision'],'note'=>$data['note']??null,'metadata'=>['previous_status'=>$before]]); $titles=['published'=>'Opportunité publiée','rejected'=>'Opportunité refusée','changes_requested'=>'Compléments demandés','suspended'=>'Opportunité suspendue']; $messages=['published'=>'Votre opportunité a été approuvée et publiée.','rejected'=>'Votre opportunité a été refusée. Motif : '.($data['note']??''),'changes_requested'=>'Des modifications sont nécessaires avant publication : '.($data['note']??''),'suspended'=>'Votre opportunité a été suspendue. Motif : '.($data['note']??'')]; OcdNotification::create(['user_id'=>$item->user_id,'type'=>'opportunity_'.$data['decision'],'title'=>$titles[$data['decision']],'message'=>$messages[$data['decision']],'data'=>['opportunity_id'=>$item->id,'status'=>$data['decision']]]); }); if ($data['decision']==='published') { \App\Models\User::where('account_type','!=','admin')->where('opportunity_alerts',true)->where('email_notifications',true)->where('id','!=',$item->user_id)->select('id')->chunkById(100,function($users) use($item) { foreach($users as $subscriber) { OcdNotification::create(['user_id'=>$subscriber->id,'type'=>'opportunity_new_published','title'=>'Nouvelle opportunité sur OCD','message'=>'Une nouvelle opportunité « '.$item->title.' » vient d’être publiée. Connectez-vous à OCD pour consulter les détails et vérifier les critères.','data'=>['opportunity_id'=>$item->id,'slug'=>$item->slug]]); } }); } return response()->json(['message'=>'Décision enregistrée.','data'=>$item->fresh()]); }
}
